def count_even(numbers: list) -> int:
    count = 0
    for n in numbers:
        if n % 2 == 0:
            count += 1
    return count

def maximum3(a: float, b: float, c: float) -> float:
    """Returns the largest of three numbers."""
    largest = a
    if b > largest:
        largest = b
    if c > largest:
        largest = c
    return largest

def count_uppercase(text: str) -> int:
    """Counts the uppercase letters in text."""
    count = 0
    for zeichen in text:
        if zeichen != zeichen.lower():
            count += 1
    return count
